     2→import express from 'express';
     3→import http from 'http';
     4→import cors from 'cors';
     5→import { Server as SocketIOServer } from 'socket.io';
     6→import { createAdapter } from '@socket.io/redis-adapter';
     7→import { connectToDatabase, closeConnection } from './db/mongodb';
     8→import { connectToRedis, getRedisClient, closeRedisConnection } from './db/redis';
     9→import config from './config';
    10→import routes from './routes';
    11→
    12→const app = express();
    13→const server = http.createServer(app);
    14→
    15→// Middleware
    16→app.use(cors({
    17→  origin: config.corsOrigin,
    18→  credentials: true
    19→}));
    20→
    21→app.use(express.json());
    22→app.use(express.urlencoded({ extended: true }));
    23→
    24→// API routes 
    25→app.use('/api', routes);
    26→
    27→// Health check endpoint
    28→app.get('/health', (req, res) => {
    29→  res.status(200).json({ status: 'ok', environment: process.env.NODE_ENV });
    30→});
    31→
    32→// Setup Socket.IO with Redis adapter
    33→const setupSocketIO = async () => {
    34→  try {
    35→    const io = new SocketIOServer(server, {
    36→      cors: {
    37→        origin: config.corsOrigin,
    38→        methods: ['GET', 'POST'],
    39→        credentials: true
    40→      }
    41→    });
    42→
    43→    // Connect to Redis for Socket.IO adapter
    44→    if (config.redisUrl) {
    45→      const { pubClient, subClient } = await getRedisClient();
    46→      io.adapter(createAdapter(pubClient, subClient));
    47→    }
    48→
    49→    // Listen for socket connections
    50→    io.on('connection', (socket) => {
    51→      console.log('New client connected:', socket.id);
    52→
    53→      // Handle disconnect
    54→      socket.on('disconnect', () => {
    55→        console.log('Client disconnected:', socket.id);
    56→      });
    57→    });
    58→
    59→    return io;
    60→  } catch (error) {
    61→    console.error('Failed to setup Socket.IO:', error);
    62→    throw error;
    63→  }
    64→};
    65→
    66→// Initialize database and start server
    67→const startServer = async () => {
    68→  try {
    69→    // Connect to MongoDB
    70→    await connectToDatabase();
    71→    
    72→    // Connect to Redis
    73→    await connectToRedis();
    74→    
    75→    // Setup Socket.IO
    76→    const io = await setupSocketIO();
    77→    
    78→    // Start the server
    79→    const PORT = config.port;
    80→    server.listen(PORT, () => {
    81→      console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
    82→      console.log(`Health check: http://localhost:${PORT}/health`);
    83→      console.log(`API base URL: http://localhost:${PORT}/api`);
    84→    });
    85→    
    86→    // Handle graceful shutdown
    87→    const shutdown = async () => {
    88→      console.log('Shutting down server...');
    89→      
    90→      // Close the HTTP server
    91→      server.close(async () => {
    92→        console.log('HTTP server closed');
    93→        
    94→        // Close database connections
    95→        await closeConnection();
    96→        await closeRedisConnection();
    97→        
    98→        process.exit(0);
    99→      });
   100→      
   101→      // Force exit after timeout if connections are stuck
   102→      setTimeout(() => {
   103→        console.error('Could not close connections in time, forcefully shutting down');
   104→        process.exit(1);
   105→      }, 10000);
   106→    };
   107→    
   108→    // Handle termination signals
   109→    process.on('SIGTERM', shutdown);
   110→    process.on('SIGINT', shutdown);
   111→    
   112→  } catch (error) {
   113→    console.error('Failed to start server:', error);
   114→    process.exit(1);
   115→  }
   116→};
   117→
   118→// Start the server
   119→startServer();
   120→
   121→// For testing
   122→export { app, server };
   123→

