     2→import { MongoClient, Db } from 'mongodb';
     3→import config from '../config';
     4→
     5→let db: Db | null = null;
     6→let client: MongoClient | null = null;
     7→
     8→export const connectToDatabase = async (): Promise<Db> => {
     9→  if (db) return db;
    10→
    11→  try {
    12→    const mongoUri = process.env.MONGODB_URI || config.mongoUri;
    13→    client = new MongoClient(mongoUri);
    14→    await client.connect();
    15→    
    16→    const dbName = process.env.MONGODB_DB_NAME || config.dbName;
    17→    db = client.db(dbName);
    18→    
    19→    console.log('Connected to MongoDB');
    20→    return db;
    21→  } catch (error) {
    22→    console.error('MongoDB connection error:', error);
    23→    throw new Error('Failed to connect to database');
    24→  }
    25→};
    26→
    27→export const getDb = async (): Promise<Db> => {
    28→  if (!db) {
    29→    return connectToDatabase();
    30→  }
    31→  return db;
    32→};
    33→
    34→export const closeConnection = async (): Promise<void> => {
    35→  if (client) {
    36→    await client.close();
    37→    db = null;
    38→    client = null;
    39→    console.log('MongoDB connection closed');
    40→  }
    41→};
    42→
    43→// Export the db variable for backward compatibility
    44→export { db };
