     2→import { createClient } from 'redis';
     3→import config from '../config';
     4→
     5→// Create a proper Redis client and export it
     6→let redisClient = null;
     7→let pubClient = null;
     8→let subClient = null;
     9→
    10→/**
    11→ * Connect to Redis server
    12→ */
    13→export const connectToRedis = async () => {
    14→  if (!config.redisUrl) {
    15→    console.log('Redis URL not provided, skipping Redis connection');
    16→    return;
    17→  }
    18→
    19→  try {
    20→    redisClient = createClient({ url: config.redisUrl });
    21→    pubClient = redisClient.duplicate();
    22→    subClient = pubClient.duplicate();
    23→
    24→    await redisClient.connect();
    25→    await pubClient.connect();
    26→    await subClient.connect();
    27→
    28→    console.log('Connected to Redis');
    29→    return redisClient;
    30→  } catch (error) {
    31→    console.error('Failed to connect to Redis:', error);
    32→    throw error;
    33→  }
    34→};
    35→
    36→/**
    37→ * Get Redis clients for Socket.IO adapter
    38→ */
    39→export const getRedisClient = async () => {
    40→  if (!pubClient || !subClient) {
    41→    if (!redisClient) {
    42→      await connectToRedis();
    43→    }
    44→    
    45→    if (!pubClient) {
    46→      pubClient = redisClient.duplicate();
    47→      await pubClient.connect();
    48→    }
    49→    
    50→    if (!subClient) {
    51→      subClient = redisClient.duplicate();
    52→      await subClient.connect();
    53→    }
    54→  }
    55→  
    56→  return { pubClient, subClient };
    57→};
    58→
    59→/**
    60→ * Get main Redis client
    61→ */
    62→export const getMainRedisClient = () => {
    63→  if (!redisClient) {
    64→    throw new Error('Redis client not initialized');
    65→  }
    66→  return redisClient;
    67→};
    68→
    69→/**
    70→ * Close Redis connection
    71→ */
    72→export const closeRedisConnection = async () => {
    73→  try {
    74→    if (redisClient) {
    75→      await redisClient.disconnect();
    76→    }
    77→    if (pubClient) {
    78→      await pubClient.disconnect();
    79→    }
    80→    if (subClient) {
    81→      await subClient.disconnect();
    82→    }
    83→    console.log('Redis connections closed');
    84→  } catch (error) {
    85→    console.error('Error closing Redis connections:', error);
    86→  }
    87→};
    88→
    89→// Export the Redis client
    90→export { redisClient };
