  name: "Start application",
  command: "cd registropolis-main && npm run dev",
  waitForPort: 5000,
  outputType: "webview"
});
console.log("Workflow configured");

const status = await getWorkflowStatus({ name: "Start application", maxScrollbackLines: 50 });
