import React from 'react';
import { ArrowLeft, Phone, Video, MoreVertical } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { cn } from '@/lib/utils';

interface ChatHeaderProps {
  contact: {
    id: string;
    name: string;
    imageUrl?: string;
    isOnline: boolean;
    lastSeen?: string;
  };
  onBackClick?: () => void;
}

const ChatHeader: React.FC<ChatHeaderProps> = ({ contact, onBackClick }) => {
  return (
    <div className="flex items-center gap-3 px-4 py-3 border-b bg-card shrink-0">
      {onBackClick && (
        <Button variant="ghost" size="icon" onClick={onBackClick} className="md:hidden h-8 w-8">
          <ArrowLeft className="h-5 w-5" />
        </Button>
      )}
      <Avatar className="h-9 w-9">
        <AvatarFallback className="bg-primary/10 text-primary font-semibold text-sm">
          {contact.name.charAt(0).toUpperCase()}
        </AvatarFallback>
      </Avatar>
      <div className="flex-1 min-w-0">
        <h3 className="font-semibold text-sm truncate">{contact.name}</h3>
        <div className="flex items-center gap-1">
          {contact.isOnline ? (
            <>
              <span className="w-1.5 h-1.5 rounded-full bg-green-500 inline-block" />
              <span className="text-xs text-green-600">Online</span>
            </>
          ) : (
            <span className="text-xs text-muted-foreground">{contact.lastSeen || 'Offline'}</span>
          )}
        </div>
      </div>
      <div className="flex items-center gap-0.5">
        <Button variant="ghost" size="icon" className="h-8 w-8">
          <Phone className="h-4 w-4" />
        </Button>
        <Button variant="ghost" size="icon" className="h-8 w-8">
          <Video className="h-4 w-4" />
        </Button>
        <Button variant="ghost" size="icon" className="h-8 w-8">
          <MoreVertical className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
};

export default ChatHeader;

import React from 'react';
import { format } from 'date-fns';
import { Check, CheckCheck, MapPin } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface Message {
  id: string;
  content: string;
  sender: 'user' | 'contact';
  timestamp: Date;
  status: 'sent' | 'delivered' | 'read';
  type: 'text' | 'image' | 'audio' | 'location';
  media?: string;
}

interface MessageListProps {
  messages: Message[];
}

const MessageBubble: React.FC<{ message: Message }> = ({ message }) => {
  const isUser = message.sender === 'user';

  return (
    <div className={cn('flex mb-1.5', isUser ? 'justify-end' : 'justify-start')}>
      <div
        className={cn(
          'max-w-[72%] rounded-2xl px-3.5 py-2 relative',
          isUser
            ? 'bg-primary text-primary-foreground rounded-br-sm'
            : 'bg-muted text-foreground rounded-bl-sm'
        )}
      >
        {message.type === 'text' && (
          <p className="text-sm leading-relaxed break-words">{message.content}</p>
        )}
        {message.type === 'image' && message.media && (
          <img
            src={message.media}
            alt="Shared"
            className="rounded-xl max-w-full max-h-52 object-cover mb-1"
          />
        )}
        {message.type === 'location' && (
          <div className="flex items-center gap-2 py-0.5">
            <MapPin className="h-4 w-4 text-blue-500 shrink-0" />
            <span className="text-sm">Shared a location</span>
          </div>
        )}
        <div
          className={cn(
            'flex items-center justify-end gap-1 mt-0.5',
            isUser ? 'text-primary-foreground/60' : 'text-muted-foreground'
          )}
        >
          <span className="text-[10px]">{format(message.timestamp, 'HH:mm')}</span>
          {isUser &&
            (message.status === 'read' ? (
              <CheckCheck className="h-3 w-3" />
            ) : (
              <Check className="h-3 w-3" />
            ))}
        </div>
      </div>
    </div>
  );
};

const MessageList: React.FC<MessageListProps> = ({ messages }) => {
  return (
    <div className="flex flex-col">
      {messages.map((message) => (
        <MessageBubble key={message.id} message={message} />
      ))}
    </div>
  );
};

export default MessageList;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Search, Send, Paperclip, Smile, ArrowLeft, MessageSquare } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import ChatHeader from '@/components/chat/ChatHeader';
import MessageList from '@/components/chat/MessageList';
import type { Message } from '@/components/chat/MessageList';
import { useIsMobile } from '@/hooks/use-mobile';

interface Contact {
  id: string;
  name: string;
  lastMessage: string;
