import React, { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import AnimatedTransition from '../common/AnimatedTransition';
import { useSidebar } from '@/context/SidebarContext';
import Sidebar from './Sidebar';
import { useAuth } from '@/context/AuthContext';
import { useIsMobile } from '@/hooks/use-mobile';

interface AppLayoutProps {
  children: React.ReactNode;
  fullWidth?: boolean;
  maxWidth?: 'sm' | 'md' | 'lg' | 'xl' | '2xl' | 'full';
  centered?: boolean;
  noAnimation?: boolean;
  withSidebar?: boolean;
  requireAuth?: boolean;
}

const AppLayout: React.FC<AppLayoutProps> = ({
  children,
  fullWidth = false,
  maxWidth = '2xl',
  centered = false,
  noAnimation = false,
  withSidebar = true,
  requireAuth = false,
}) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { isCollapsed, contentMargin, sidebarTransitionClass, setSidebarCollapsed } = useSidebar();
  const { isAuthenticated, isLoading } = useAuth();
  const isMobile = useIsMobile();

  const isHomepage = location.pathname === '/';

  useEffect(() => {
    if (requireAuth && !isLoading && !isAuthenticated) {
      navigate('/auth', { state: { from: location.pathname } });
    }
  }, [requireAuth, isAuthenticated, isLoading, navigate, location.pathname]);

  useEffect(() => {
    if (isMobile && withSidebar) {
      setSidebarCollapsed(true);
    }
  }, [location.pathname, isMobile, withSidebar, setSidebarCollapsed]);

  const maxWidthClasses: Record<string, string> = {
    sm: 'max-w-screen-sm',
    md: 'max-w-screen-md',
    lg: 'max-w-screen-lg',
    xl: 'max-w-screen-xl',
    '2xl': 'max-w-screen-2xl',
    full: 'max-w-full',
  };

  return (
    <div className="h-screen flex overflow-hidden bg-background w-full" data-testid="app-layout">
      {withSidebar && <Sidebar />}

      <main
        style={withSidebar && !isMobile ? { marginLeft: `${contentMargin}px` } : undefined}
        className={[
          'flex-1 h-full overflow-hidden',
          'transition-all duration-300 ease-in-out',
          sidebarTransitionClass,
          fullWidth ? '' : 'px-2 sm:px-4 lg:px-6',
          !fullWidth && !isHomepage ? maxWidthClasses[maxWidth] : '',
          centered ? 'flex items-center justify-center' : '',
          isHomepage ? 'w-full max-w-full p-0 overflow-y-auto' : '',
          'w-full',
        ]
          .filter(Boolean)
          .join(' ')}
        data-mobile={isMobile ? 'true' : 'false'}
      >
        {noAnimation ? (
          children
        ) : (
          <AnimatePresence mode="wait">
            <AnimatedTransition key={location.pathname}>
              {children}
            </AnimatedTransition>
          </AnimatePresence>
        )}
      </main>
    </div>
  );
};

export default AppLayout;

import React from 'react';
import { motion } from 'framer-motion';

interface AnimatedTransitionProps {
  children: React.ReactNode;
  duration?: number;
}

const AnimatedTransition: React.FC<AnimatedTransitionProps> = ({
  children,
  duration = 0.25,
}) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 6 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 6 }}
      transition={{ duration, ease: [0.22, 1, 0.36, 1] }}
      className="w-full h-full"
    >
      {children}
    </motion.div>
  );
};

export default AnimatedTransition;

import React from 'react';
import DashboardContent from './DashboardContent';

interface DashboardContentWrapperProps {
  initialSection?: string;
}

const DashboardContentWrapper: React.FC<DashboardContentWrapperProps> = ({
  initialSection = 'messages',
}) => {
  return (
    <div className="h-full">
      <DashboardContent activeSection={initialSection} />
    </div>
  );
};

export default DashboardContentWrapper;

import React from 'react';
import { useBusinessDataInit } from '@/hooks/useBusinessDataInit';
import DashboardSection from './DashboardSection';

interface DashboardContentProps {
  activeSection: string;
}

const DashboardContent: React.FC<DashboardContentProps> = ({ activeSection }) => {
  useBusinessDataInit();

  return (
    <div className="h-full">
      <DashboardSection activeSection={activeSection} />
    </div>
  );
};

export default DashboardContent;

import React, { Suspense } from 'react';
import DashboardLoadingSection from './DashboardLoadingSection';

const MessagesSection = React.lazy(() => import('../messages/MessagesSection'));
const BusinessSection = React.lazy(() => import('../business/BusinessSection'));
const JobsSection = React.lazy(() => import('../jobs/JobsSection'));
const MarketplaceSection = React.lazy(() => import('../marketplace/MarketplaceSection'));
const RealEstateSection = React.lazy(() => import('../real-estate/RealEstateSection'));
const TaxiSection = React.lazy(() => import('../taxi/TaxiSection'));
const FoodSection = React.lazy(() => import('../food/FoodSection'));
const ServicesSection = React.lazy(() => import('../services/ServicesSection'));
const TransportSection = React.lazy(() => import('../transport/TransportSection'));
const EventsSection = React.lazy(() => import('../events/EventsSection'));
const SettingsSection = React.lazy(() => import('../settings/SettingsSection'));

interface DashboardSectionProps {
  activeSection: string;
}

const DashboardSection: React.FC<DashboardSectionProps> = ({ activeSection }) => {
  const isFullHeight = activeSection === 'messages';

  const renderSection = () => {
    switch (activeSection) {
      case 'messages':    return <MessagesSection />;
      case 'business':    return <BusinessSection />;
      case 'jobs':        return <JobsSection />;
      case 'services':    return <ServicesSection />;
      case 'marketplace': return <MarketplaceSection />;
      case 'real-estate': return <RealEstateSection />;
      case 'taxi':        return <TaxiSection />;
      case 'transport':   return <TransportSection />;
      case 'food':        return <FoodSection />;
      case 'events':      return <EventsSection />;
      case 'settings':    return <SettingsSection />;
      default:            return <MessagesSection />;
    }
  };

  return (
    <Suspense fallback={<DashboardLoadingSection />}>
      <div className={isFullHeight ? 'h-full overflow-hidden' : 'h-full overflow-y-auto pb-20'}>
        {renderSection()}
      </div>
    </Suspense>
  );
};

export default DashboardSection;

import React, { useEffect } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import AppLayout from '@/components/layout/AppLayout';
import DashboardContentWrapper from '@/components/dashboard/DashboardContentWrapper';
import { useAuthPrompt } from '@/hooks/useAuthPrompt';
import { useAuth } from '@/context/AuthContext';
import { Loader2 } from 'lucide-react';
import { useIsMobile } from '@/hooks/use-mobile';

const Dashboard: React.FC = () => {
  const { section } = useParams<{ section?: string }>();
  const location = useLocation();
  const isMobile = useIsMobile();

  const state = location.state as { section?: string } | null;
  const activeSection = section || state?.section || 'messages';

  const { checkAuthAndPrompt } = useAuthPrompt();
  const { isLoading } = useAuth();

  useEffect(() => {
    checkAuthAndPrompt();
  }, [checkAuthAndPrompt, activeSection]);

  if (isLoading) {
    return (
      <div className="w-full h-screen flex items-center justify-center">
        <Loader2 className="h-12 w-12 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <AppLayout
      withSidebar={true}
      fullWidth={activeSection === 'messages' || isMobile}
      maxWidth={isMobile ? 'full' : '2xl'}
      noAnimation={activeSection === 'messages'}
    >
      <DashboardContentWrapper initialSection={activeSection} />
    </AppLayout>
  );
};

export default Dashboard;

