import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider } from "@/context/AuthContext";
import { SidebarProvider } from "@/context/SidebarContext";
import Index from "./pages/Index";
import Dashboard from "./pages/Dashboard";
import NotFound from "./pages/NotFound";
import Admin from "./pages/Admin";
import { AnimatePresence } from "framer-motion";
import { useEffect } from "react";

document.title = "Buzzer - Connect & Share";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
      staleTime: 5 * 60 * 1000,
    },
  },
});

const ThemeInitializer = () => {
  useEffect(() => {
    document.documentElement.classList.remove('dark');
    document.documentElement.classList.add('light');
  }, []);
  return null;
};

const App = () => (
  <QueryClientProvider client={queryClient}>
    <ThemeInitializer />
    <AuthProvider>
      <BrowserRouter>
        <SidebarProvider>
          <div className="w-full min-h-screen">
            <TooltipProvider>
              <Toaster />
              <Sonner />
              <AnimatePresence mode="wait">
                <Routes>
                  <Route path="/" element={<Index />} />
                  <Route path="/dashboard" element={<Dashboard />} />
                  <Route path="/dashboard/:section" element={<Dashboard />} />
                  <Route path="/admin" element={<Admin />} />

                  {/* Legacy / removed routes — redirect to dashboard */}
                  <Route path="/auth" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/setup" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/messages" element={<Navigate to="/dashboard/messages" replace />} />
                  <Route path="/messages/:chatId" element={<Navigate to="/dashboard/messages" replace />} />
                  <Route path="/food" element={<Navigate to="/dashboard/food" replace />} />
                  <Route path="/taxi" element={<Navigate to="/dashboard/taxi" replace />} />
                  <Route path="/marketplace" element={<Navigate to="/dashboard/marketplace" replace />} />
                  <Route path="/business" element={<Navigate to="/dashboard/business" replace />} />
                  <Route path="/jobs" element={<Navigate to="/dashboard/jobs" replace />} />
                  <Route path="/services" element={<Navigate to="/dashboard/services" replace />} />
                  <Route path="/real-estate" element={<Navigate to="/dashboard/real-estate" replace />} />
                  <Route path="/transport" element={<Navigate to="/dashboard/transport" replace />} />
                  <Route path="/events" element={<Navigate to="/dashboard/events" replace />} />
                  <Route path="/settings" element={<Navigate to="/dashboard/settings" replace />} />

                  <Route path="*" element={<NotFound />} />
                </Routes>
              </AnimatePresence>
            </TooltipProvider>
          </div>
        </SidebarProvider>
      </BrowserRouter>
    </AuthProvider>
  </QueryClientProvider>
);

export default App;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import AppLayout from '@/components/layout/AppLayout';
import { Button } from '@/components/ui/button';
import {
  MessageSquare,
  Pizza,
  Car,
  ShoppingBag,
  Briefcase,
  Building,
  Calendar,
  ArrowRight,
  ShieldCheck,
} from 'lucide-react';

const features = [
  { icon: <MessageSquare className="w-12 h-12 text-blue-500" />,    title: 'Instant Messaging', description: 'Connect with businesses and users through real-time messaging.',           section: 'messages' },
  { icon: <Pizza className="w-12 h-12 text-orange-500" />,          title: 'Food Delivery',      description: 'Order from local restaurants or become a home chef.',                   section: 'food' },
  { icon: <Car className="w-12 h-12 text-green-500" />,             title: 'Taxi Services',       description: 'Book rides and negotiate fares directly with drivers.',                  section: 'taxi' },
  { icon: <ShoppingBag className="w-12 h-12 text-purple-500" />,    title: 'Marketplace',         description: 'Buy, sell, or trade items in your local community.',                    section: 'marketplace' },
  { icon: <Briefcase className="w-12 h-12 text-indigo-500" />,      title: 'Jobs',                description: 'Find job opportunities or post positions for your business.',            section: 'jobs' },
  { icon: <Building className="w-12 h-12 text-red-500" />,          title: 'Real Estate',         description: 'Browse properties, connect with agents, find your next home.',          section: 'real-estate' },
  { icon: <Calendar className="w-12 h-12 text-teal-500" />,         title: 'Events',              description: 'Discover and organize local events in your community.',                  section: 'events' },
  { icon: <ShieldCheck className="w-12 h-12 text-cyan-500" />,      title: 'Secure Platform',     description: 'Sign in to unlock full features while browsing freely as a guest.',     section: 'settings' },
];

const Index = () => {
  const navigate = useNavigate();

  return (
    <AppLayout centered={false} withSidebar={false}>
      <div className="relative w-full min-h-screen overflow-hidden bg-gradient-to-b from-background to-background/80">
        <div className="absolute top-0 -left-4 w-96 h-96 bg-blue-500/10 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-float" />
        <div className="absolute bottom-0 right-0 w-96 h-96 bg-purple-500/10 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-float" style={{ animationDelay: '2s' }} />

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 sm:py-24">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="text-center mb-16 sm:mb-20"
          >
            <h1 className="text-4xl sm:text-5xl md:text-6xl font-bold tracking-tight mb-6 bg-gradient-to-r from-primary to-purple-500 bg-clip-text text-transparent">
              Your All-in-One Platform
            </h1>
            <p className="text-lg sm:text-xl text-muted-foreground mb-8 max-w-3xl mx-auto">
              Browse services freely as a guest. Sign in from the sidebar to unlock messaging and full features.
            </p>
            <Button
              size="lg"
              onClick={() => navigate('/dashboard')}
              className="group text-lg px-8 py-6 rounded-full shadow-lg hover:shadow-xl transition-all duration-300"
            >
              Get Started
              <ArrowRight className="ml-2 w-5 h-5 group-hover:translate-x-1 transition-transform" />
            </Button>
          </motion.div>

          <motion.section
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
            className="text-center"
          >
            <h2 className="text-3xl sm:text-4xl font-bold mb-16 text-foreground">Explore Our Features</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 sm:gap-8">
              {features.map((f, i) => (
                <motion.div
                  key={f.section}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ duration: 0.4, delay: 0.4 + i * 0.07 }}
                  className="glass-morphism p-6 rounded-2xl hover:scale-105 transition-transform duration-300 cursor-pointer"
                  onClick={() => navigate(`/dashboard/${f.section}`)}
                >
                  <div className="flex justify-center mb-6">{f.icon}</div>
                  <h3 className="text-xl font-semibold mb-3">{f.title}</h3>
                  <p className="text-muted-foreground">{f.description}</p>
                </motion.div>
              ))}
            </div>
          </motion.section>
        </div>
      </div>
    </AppLayout>
  );
};

export default Index;

import React from 'react';
import { useParams, useLocation } from 'react-router-dom';
import AppLayout from '@/components/layout/AppLayout';
import DashboardContentWrapper from '@/components/dashboard/DashboardContentWrapper';
import { useAuth } from '@/context/AuthContext';
import { Loader2 } from 'lucide-react';
import { useIsMobile } from '@/hooks/use-mobile';

const Dashboard: React.FC = () => {
  const { section } = useParams<{ section?: string }>();
  const location = useLocation();
  const isMobile = useIsMobile();
  const { isLoading } = useAuth();

  const state = location.state as { section?: string } | null;
  const activeSection = section || state?.section || 'messages';

  if (isLoading) {
    return (
      <div className="w-full h-screen flex items-center justify-center">
        <Loader2 className="h-12 w-12 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <AppLayout
      withSidebar={true}
      fullWidth={activeSection === 'messages' || isMobile}
      maxWidth={isMobile ? 'full' : '2xl'}
      noAnimation={activeSection === 'messages'}
    >
      <DashboardContentWrapper initialSection={activeSection} />
    </AppLayout>
  );
};

export default Dashboard;

import React, { createContext, useContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { toast } from 'sonner';
import { authAPI } from '@/services/apiService';

type User = {
  id: string;
  phoneNumber?: string;
  name: string;
  profileImageUrl?: string;
  email?: string;
  role?: string;
};

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  isAdmin: boolean;
  signIn: (user: User) => void;
  signOut: () => void;
  refreshUser: () => Promise<void>;
  addAdmin: (email: string) => Promise<void>;
}

const defaultAuthContext: AuthContextType = {
  user: null,
  isLoading: true,
  isAuthenticated: false,
  isAdmin: false,
  signIn: () => {},
  signOut: () => {},
  refreshUser: async () => {},
  addAdmin: async () => {},
};

const AuthContext = createContext<AuthContextType>(defaultAuthContext);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const storedUser = localStorage.getItem('user');
        const token = localStorage.getItem('auth_token');
        if (storedUser && token) {
          try {
            const response = await authAPI.getCurrentUser();
            if (response?.user) {
              setUser(response.user);
            } else {
              localStorage.removeItem('user');
              localStorage.removeItem('auth_token');
            }
          } catch {
            localStorage.removeItem('user');
            localStorage.removeItem('auth_token');
          }
        }
      } finally {
        setIsLoading(false);
      }
    };
    checkAuth();
  }, []);

  const signIn = (userData: User) => {
    localStorage.setItem('user', JSON.stringify(userData));
    setUser(userData);
    toast.success(`Welcome, ${userData.name}!`);
  };

  const signOut = async () => {
    try {
      if (user) await authAPI.logout();
    } catch {
      // ignore
    } finally {
      localStorage.removeItem('user');
      localStorage.removeItem('auth_token');
      localStorage.removeItem('mock_user');
      setUser(null);
      toast.success('Signed out successfully');
    }
  };

  const refreshUser = async () => {
    try {
      const response = await authAPI.getCurrentUser();
      if (response?.user) {
        setUser(response.user);
        localStorage.setItem('user', JSON.stringify(response.user));
      }
    } catch {
      // ignore
    }
  };

  const addAdmin = async (email: string) => {
    try {
      await authAPI.addAdmin(email);
      toast.success(`${email} is now an admin`);
    } catch (error) {
      toast.error('Failed to add admin: ' + (error instanceof Error ? error.message : 'Unknown error'));
    }
  };

  const isAdmin = useMemo(
    () => !!user && (user.role === 'admin' || user.email === 'admin'),
    [user]
  );

  const value = useMemo(
    () => ({ user, isLoading, isAuthenticated: !!user, isAdmin, signIn, signOut, refreshUser, addAdmin }),
    [user, isLoading, isAdmin]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '@/context/AuthContext';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Shield } from 'lucide-react';

const AdminRouteGuard: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isAdmin, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <span className="text-muted-foreground">Loading…</span>
      </div>
