      <SidebarItem
        icon={<Settings size={20} />}
        title="Settings"
        href="/dashboard/settings"
        isCollapsed={isCollapsed}
        isActive={location.pathname === '/dashboard/settings'}
        onClick={onItemClick}
      />

      {isAuthenticated ? (
        <>
          {!isCollapsed && user && (
            <div className="px-3 py-2 rounded-lg bg-muted/40 mx-1 mb-1">
