    44→  localStorage.setItem('mock_user', JSON.stringify(user));
    45→  localStorage.setItem('user', JSON.stringify(user));
    46→  localStorage.setItem('auth_token', token);
    47→  
    48→  return { user, token };
    49→};
    50→
    51→/**
    52→ * Check if a user is signed in
