import React, { Suspense } from 'react';
import DashboardLoadingSection from './DashboardLoadingSection';

const MessagesSection   = React.lazy(() => import('../messages/MessagesSection'));
const MarketplaceSection = React.lazy(() => import('../marketplace/MarketplaceSection'));
const JobsSection       = React.lazy(() => import('../jobs/JobsSection'));
const ServicesSection   = React.lazy(() => import('../services/ServicesSection'));
const RealEstateSection = React.lazy(() => import('../real-estate/RealEstateSection'));
const TransportSection  = React.lazy(() => import('../transport/TransportSection'));
const EventsSection     = React.lazy(() => import('../events/EventsSection'));
const SettingsSection   = React.lazy(() => import('../settings/SettingsSection'));
const BusinessSection   = React.lazy(() => import('../business/BusinessSection'));

interface DashboardSectionProps {
  activeSection: string;
}

const DashboardSection: React.FC<DashboardSectionProps> = ({ activeSection }) => {
  const isFullHeight = activeSection === 'messages';

  const renderSection = () => {
    switch (activeSection) {
      case 'messages':    return <MessagesSection />;
      case 'marketplace': return <MarketplaceSection />;
      case 'jobs':        return <JobsSection />;
      case 'services':    return <ServicesSection />;
      case 'real-estate': return <RealEstateSection />;
      case 'transport':   return <TransportSection />;
      case 'events':      return <EventsSection />;
      case 'settings':    return <SettingsSection />;
      case 'business':    return <BusinessSection />;
      default:            return <MessagesSection />;
    }
  };

  return (
    <Suspense fallback={<DashboardLoadingSection />}>
      <div className={isFullHeight ? 'h-full overflow-hidden' : 'h-full overflow-y-auto pb-20'}>
        {renderSection()}
      </div>
    </Suspense>
  );
};

export default DashboardSection;

import React from 'react';
import { cn } from '@/lib/utils';
import { Zap } from 'lucide-react';

interface SidebarHeaderProps {
  isCollapsed: boolean;
}

const SidebarHeader: React.FC<SidebarHeaderProps> = ({ isCollapsed }) => {
  return (
    <div
      className={cn(
        'flex items-center h-[60px] px-4 border-b border-sidebar-border',
        isCollapsed ? 'justify-center' : 'justify-start gap-3'
      )}
    >
      <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center flex-shrink-0 shadow-sm">
        <Zap className="w-4 h-4 text-white" strokeWidth={2.5} />
      </div>
      {!isCollapsed && (
        <div className="min-w-0">
          <span className="text-[15px] font-bold tracking-tight text-foreground">Buzzer</span>
          <span className="block text-[10px] text-muted-foreground font-medium tracking-widest uppercase leading-none mt-0.5">Community</span>
        </div>
      )}
    </div>
  );
};

export default SidebarHeader;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';

interface SidebarItemProps {
  icon: React.ReactNode;
  title: string;
  href: string;
  isCollapsed: boolean;
  isActive?: boolean;
  subItems?: { title: string; href: string }[];
  badge?: string;
  isNew?: boolean;
  onClick?: () => void;
}

const SidebarItem: React.FC<SidebarItemProps> = ({
  icon, title, href, isCollapsed, isActive, subItems, badge, isNew = false, onClick,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const hasSubItems = subItems && subItems.length > 0;
  const location = useLocation();

  const handleClick = (e: React.MouseEvent) => {
    if (hasSubItems) {
      e.preventDefault();
      setIsOpen(!isOpen);
    } else if (onClick) {
      onClick();
    }
  };

  return (
    <div className="w-full" data-testid={`sidebar-item-${title?.toLowerCase() ?? 'item'}`}>
      <Link
        to={href}
        className={cn(
          'group flex items-center gap-2.5 px-2.5 py-2 rounded-lg text-sm font-medium transition-all duration-150 w-full relative select-none',
          isActive
            ? 'bg-primary/8 text-primary [&_svg]:text-primary'
            : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800 [&_svg]:text-slate-400 hover:[&_svg]:text-slate-600'
        )}
        style={isActive ? { backgroundColor: 'color-mix(in srgb, hsl(var(--primary)) 8%, transparent)' } : undefined}
        onClick={handleClick}
      >
        <div className={cn('relative flex-shrink-0', isCollapsed ? 'mx-auto' : '')}>
          {icon}
          {badge && isCollapsed && (
            <span className="absolute -top-1 -right-1 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-red-500 text-[9px] text-white font-bold">
              {parseInt(badge) > 9 ? '9+' : badge}
            </span>
          )}
        </div>

        {!isCollapsed && (
          <>
            <span className="flex-1 truncate">{title}</span>
            {isNew && (
              <span className="text-[10px] font-semibold bg-primary text-white px-1.5 py-0.5 rounded-full leading-none">
                New
              </span>
            )}
            {badge && (
              <span className={cn(
                'text-[11px] font-semibold px-1.5 py-0.5 rounded-full min-w-[20px] text-center leading-none',
                isActive ? 'bg-primary text-white' : 'bg-red-500 text-white'
              )}>
                {parseInt(badge) > 99 ? '99+' : badge}
              </span>
            )}
            {hasSubItems && (
              <ChevronRight
                className={cn('h-3.5 w-3.5 text-slate-400 transition-transform duration-150', isOpen && 'rotate-90')}
              />
            )}
          </>
        )}
      </Link>

      {hasSubItems && isOpen && !isCollapsed && (
        <div className="pl-8 mt-0.5 space-y-0.5">
          {subItems!.map((item, idx) => (
            <Link
              key={idx}
              to={item.href}
              className={cn(
                'block px-3 py-1.5 rounded-lg text-sm transition-colors',
