                <Button size="sm" variant="outline" className="h-7 text-xs gap-1 rounded-lg">
                  <MessageCircle className="h-3 w-3" />
                  Chat
                </Button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="text-center py-20">
          <div className="w-16 h-16 rounded-2xl bg-slate-100 flex items-center justify-center mx-auto mb-4">
            <Search className="h-8 w-8 text-slate-400" />
          </div>
          <h3 className="font-semibold text-slate-700">No results found</h3>
          <p className="text-sm text-muted-foreground mt-1">Try a different search term or category</p>
        </div>
      )}
    </div>
  );
}

